# v36: UI/UX review fixes (Users table and actions, confirmations, home layout, navigation, timers, real exports,
# audit log, gradebook, progress numbers, reminders, toast, Kirkpatrick in Reports).
import asyncio, os
ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..'))
from playwright.async_api import async_playwright
EXE = os.environ.get('CHROME') or (lambda d: d if os.path.exists(d) else None)('/opt/pw-browsers/chromium_headless_shell-1208/chrome-headless-shell-linux64/chrome-headless-shell')
WEB = os.environ.get('SF_WEB', 'public')
RES=[]
def ok(n,c,x=''): RES.append((n,bool(c))); print(('PASS ' if c else 'FAIL ')+n, '' if c else str(x)[:300], flush=True)
async def open_app(b, vw, vh, errs):
    pg = await b.new_page(viewport={'width':vw,'height':vh}, accept_downloads=True)
    await pg.add_init_script(path=os.path.join(ROOT, 'tests/e2e/hook.js')); pg.on('pageerror', lambda e: errs.append(str(e)))
    await pg.goto('file://' + ROOT + '/' + WEB + '/index.html'); await pg.wait_for_selector('#sf-user')
    await pg.locator('.sf-demo2-b').filter(has_text='Learner').click(); await pg.get_by_role('button', name='Login', exact=True).click(); await pg.wait_for_timeout(700)
    return pg
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(executable_path=EXE); errs=[]
        pg = await open_app(b, 1366, 768, errs)
        S = lambda e: pg.evaluate(f"(() => {{ const s = window.__app.state; return {e}; }})()"); W = lambda ms=300: pg.wait_for_timeout(ms); R = lambda e: pg.evaluate(f"(() => {{ const r = window.__app.renderVals(); return {e}; }})()")
        y = await pg.evaluate("(() => { const c = document.querySelector('.learner-dashboard-7'); return c ? c.getBoundingClientRect().top : 9999; })()")
        ok('home: Continue learning is in the first screen (laptop)', y < 400, y)
        ok('home: the five tiles are one summary line', await pg.evaluate("document.querySelector('.sf-sum').getBoundingClientRect().height < 60 && !document.querySelector('.sf-stats')"))
        n = await R("r.annShow.length"); tot = await R("r.liveAnns.length")
        ok('home: one announcement at a time', n == 1 and tot >= 1, (n, tot))
        if tot > 1:
            await pg.locator('.sf-ann-more').click(); await W()
            ok('home: “Show all” lists every announcement', await R("r.annShow.length") == tot)
        ok('home: announcements are not black', await pg.evaluate("[...document.querySelectorAll('.sf-ann')].every(a => getComputedStyle(a).backgroundColor !== 'rgb(22, 50, 79)')"))
        act = "[...document.querySelectorAll('.hdr-7 button')].filter(b => getComputedStyle(b).backgroundColor === 'rgb(22, 50, 79)').map(b => b.textContent.trim())"
        await R("r.resumeCourse()"); await W(500)
        ok('nav: a course opened from Home highlights Home', await pg.evaluate(act) == ['Home'], await pg.evaluate(act))
        await pg.evaluate("window.__app.go('catalog')"); await W(); await pg.evaluate("window.__app.go('course', { courseId: window.__app.state.adminCourses[0].id })"); await W()
        ok('nav: a course opened from Catalog highlights Catalog', await pg.evaluate(act) == ['Catalog'], await pg.evaluate(act))
        await pg.evaluate("window.__app.go('progress')"); await W(); await pg.evaluate("window.__app.go('course', { courseId: window.__app.state.adminCourses[0].id })"); await W()
        ok('nav: a course opened from My learning highlights My learning', await pg.evaluate(act) == ['My learning'], await pg.evaluate(act))
        await pg.evaluate("window.__app.go('progress')"); await W(400)
        sc = await R("r.statCards.map(x => x.v)"); nc = await R("r.certs.length")
        ok('progress: certificate count matches the certificates listed', str(sc[2]) == str(nc), (sc, nc))
        ok('progress: no fixed sample numbers', sc[1] != '26.5h' and await R("!r.skills.some(x => x.name === 'Change leadership')"), sc)
        src = open(os.path.join(ROOT, 'public/js/learner/player.js')).read(); html = open(os.path.join(ROOT, 'public/index.html')).read()
        ok('player: friendlier timer wording, not announced every second', 'Take your time' in src and '<div class="vw" role="status">' not in html)
        ok('toast: screen-reader live region always present', await pg.evaluate("!!document.querySelector('.sf-sr[aria-live=polite]')"))
        await pg.evaluate("window.__app.toastMsg('Hello there')"); await W(200)
        await pg.locator('.ovl-33x').click(); await W(200)
        ok('toast: can be closed', await S("s.toast === null"))
        await pg.evaluate("window.__app.toastMsg('x')"); await W(2400)
        ok('toast: still closes by itself', await S("s.toast === 'x'"))
        await W(800); ok('toast: gone after a few seconds', await S("s.toast === null"))
        await pg.evaluate("window.__app.go('users', { adminView:true, role:'admin', meName:'Lena Fischer', meRole:'admin' })"); await W(500)
        chips = await pg.evaluate("[...document.querySelectorAll('.ua-sel option')].map(o => o.textContent.trim())")   # v39: filters are dropdowns
        ok('users: filter chips say “All statuses” and “All roles”', any(c.startswith('All statuses') for c in chips) and 'All roles' in chips, chips)
        ov = await pg.evaluate("""(() => { const h = document.querySelector('.users-and-accounts-13'), sp = [...h.children], last = sp.find(e => e.textContent === 'LAST ACTIVE'), act = h.querySelector('.ua-act'); return act.getBoundingClientRect().left >= last.getBoundingClientRect().right - 2; })()""")
        ok('users: the actions column no longer covers Last active / Terms', ov)
        ok('users: one labelled button per row (no unlabelled icons)', await pg.evaluate("document.querySelectorAll('.users-and-accounts-15 .ua-b').length === 0 && document.querySelectorAll('.users-and-accounts-15 .ua-mng').length > 0"))
        ok('users: row tick-boxes are named checkboxes', await pg.evaluate("[...document.querySelectorAll('.users-and-accounts-15 [role=checkbox]')].every(e => /^Select .+/.test(e.getAttribute('aria-label')) && ['true','false'].includes(e.getAttribute('aria-checked')))"))
        d0 = await S("s.users.filter(u => u.status === 'Deactivated').length"); a0 = await S("s.audit.length")
        await pg.locator('.ua-mng').first.click(); await W()
        items = await pg.evaluate("[...document.querySelectorAll('.um-i > b')].map(b => b.textContent)")
        ok('users: Manage lists labelled actions', 'View learning' in items and 'Reset password' in items and 'Deactivate account' in items, items)
        await pg.locator('.um-danger').click(); await W()
        ok('users: deactivate asks first (nothing changed yet)', await S("s.users.filter(u => u.status === 'Deactivated').length") == d0 and await pg.evaluate("!!document.querySelector('[role=alertdialog]')"))
        await pg.get_by_role('button', name='Cancel', exact=True).click(); await W()
        ok('users: Cancel keeps the account active', await S("s.users.filter(u => u.status === 'Deactivated').length") == d0)
        await pg.locator('.ua-mng').first.click(); await W(); await pg.locator('.um-danger').click(); await W()
        await pg.get_by_role('button', name='Deactivate', exact=True).click(); await W()
        ok('users: confirmed deactivate works', await S("s.users.filter(u => u.status === 'Deactivated').length") == d0 + 1)
        ok('users: deactivate is written to the audit log', await S("s.audit.length") == a0 + 1 and await S("s.audit[0].action") == 'Deactivated account')
        await pg.locator('.ua-mng').nth(1).click(); await W(); await pg.locator('.um-i').filter(has_text='Edit details').click(); await W()
        ok('users: Edit details closes the Manage menu', await S("!s.uMng && s.userModal"))
        await pg.evaluate("window.__app.setState({ userModal:false })"); await W()
        await pg.evaluate("window.__app.setState(st => ({ uSel: { [st.users[2].id]: true, [st.users[3].id]: true } }))"); await W()
        await pg.get_by_role('button', name='Deactivate', exact=True).first.click(); await W()
        ok('users: bulk deactivate asks first', await pg.evaluate("!!document.querySelector('[role=alertdialog]')") and await S("s.users[2].status") != 'Deactivated')
        await pg.get_by_role('button', name='Cancel', exact=True).click(); await W()
        await pg.locator('.ua-mng').nth(1).click(); await W(); await pg.locator('.um-i').filter(has_text='View learning').click(); await W(400)
        ok('users: View learning opens Reports for that person', await S("s.screen === 'reports' && !!s.repUser"))
        await pg.evaluate("window.__app.go('users', { adminView:true })"); await W()
        await pg.evaluate("window.__app.setState(st => ({ uSel: { [st.users.find(u => u.name === 'Jonas Berg').id]: true } }))"); await W()
        await pg.get_by_role('button', name='Send reminder', exact=True).click(); await W()
        ok('reminders: stored for the person', await S("((s.nudges || {})['Jonas Berg'] || []).length === 1"))
        ok('reminders: message is honest about e-mail', 'E-mail' in (await S("s.toast || ''")))
        await pg.evaluate("window.__app.go('audit', { adminView:true })"); await W()
        async with pg.expect_download() as dl: await pg.get_by_role('button', name='Export', exact=True).click()
        txt = open(await (await dl.value).path(), encoding='utf-8').read()
        ok('audit: Export downloads a CSV with the rows', 'When' in txt.splitlines()[0], txt[:60])
        ok('audit: the export includes this session’s actions', 'Deactivated account' in txt and 'Sent reminder' in txt)
        await pg.evaluate("window.__app.go('gradebook', { adminView:true })"); await W(600)
        rows = await R("r.gbRows.length")
        ok('gradebook: rows come from real people, courses and scores', rows > 0 and await pg.evaluate("(() => { const s = window.__app.state, r = window.__app.renderVals().gbRows; return r.every(x => s.users.some(u => u.name === x.name) && s.adminCourses.some(a => a.title === x.course)); })()"), rows)
        async with pg.expect_download() as dl2: await pg.get_by_role('button', name='Export CSV', exact=True).click()
        t2 = open(await (await dl2.value).path(), encoding='utf-8').read()
        ok('gradebook: Export CSV downloads a file', 'Learner' in t2.splitlines()[0])
        await pg.evaluate("window.__app.go('feedback', { adminView:true })"); await W(500)
        ok('kirkpatrick: the old feedback link opens Reports › Kirkpatrick analysis', await S("s.screen === 'reports' && s.repType === 'kirkpatrick'") and await pg.evaluate("!!document.querySelector('.rep-kp') && !document.querySelector('.reports-7')"))
        ok('kirkpatrick: it is the first report card', (await R("r.repTypes[0].label")).startswith('Kirkpatrick'))
        ok('kirkpatrick: levels and results are shown', await pg.evaluate("document.querySelectorAll('.rep-kp .fb-res').length > 0"))
        await pg.evaluate("window.__app.setState({ repType:'learning' })"); await W()
        ok('kirkpatrick: other reports still show their table', await pg.evaluate("!document.querySelector('.rep-kp') && !!document.querySelector('.reports-7')"))
        await pg.evaluate("window.__app.setState({ role:'instructor', meName:'Daniel Reyes', meRole:'instructor', repType:'kirkpatrick' })"); await W(400)
        ok('kirkpatrick: a trainer without the feedback permission does not get it', await R("!r.repTypes.some(t => t.label.startsWith('Kirkpatrick'))") and await pg.evaluate("!document.querySelector('.rep-kp')"))
        await pg.evaluate("window.__app.setState({ adminView:false, role:'learner', meName:'Jonas Berg', meRole:'learner', screen:'home' })"); await W(400)
        ok('reminders: shown in the person’s bell', await R("r.notifs.some(n => n.t.startsWith('Reminder from Lena Fischer'))"))
        ok('NO JS ERRORS (laptop)', not errs, errs[:3]); await pg.close()
        errs2 = []; pg = await open_app(b, 390, 844, errs2)
        y = await pg.evaluate("document.querySelector('.learner-dashboard-7').getBoundingClientRect().top")
        ok('phone: Continue learning is in the first screen', y < 700, y)
        ok('phone: the menu shows it scrolls (thin scrollbar)', await pg.evaluate("(() => { const n = document.querySelector('.hdr-7'); return n.scrollWidth > n.clientWidth && getComputedStyle(n).scrollbarWidth === 'thin'; })()"))
        await pg.evaluate("window.__app.renderVals().resumeCourse()"); await pg.wait_for_timeout(500)
        ok('phone: the lesson page does not scroll sideways', await pg.evaluate("document.documentElement.scrollWidth <= innerWidth"))
        cid = await pg.evaluate("(() => { const s = window.__app.state; const c = s.adminCourses.find(a => (s.enroll['Maya Okafor'] || {})[a.id] && a.items.length > 1); return c ? c.id : s.adminCourses[0].id; })()")
        await pg.evaluate(f"window.__app.go('item', {{ courseId:{cid!r}, itemIdx:0 }})"); await pg.wait_for_timeout(500)
        st = await pg.evaluate("(() => { const n = document.querySelector('.sf-step-nav'); return n ? getComputedStyle(n).position : 'none'; })()")
        ok('phone: Previous / Next stay pinned at the bottom of a step', st == 'sticky', st)
        await pg.evaluate("window.__app.toastMsg('Welcome, Maya')"); await pg.wait_for_timeout(200)
        lift = await pg.evaluate("(() => { const t = document.querySelector('.ovl-33'), n = document.querySelector('.sf-step-nav'); return t && n ? t.getBoundingClientRect().bottom <= n.getBoundingClientRect().top + 1 || n.getBoundingClientRect().top > innerHeight : null; })()")
        ok('phone: messages sit above the step navigation', lift, lift)
        await pg.evaluate("window.__app.go('discussions')"); await pg.wait_for_timeout(300)
        ok('phone: Discussions fits the screen', await pg.evaluate("document.documentElement.scrollWidth <= innerWidth"))
        ok('NO JS ERRORS (phone)', not errs2, errs2[:3])
        await b.close()
    print('SUMMARY', sum(c for _,c in RES), '/', len(RES))
asyncio.run(main())
